for project in records:
    if project.khach_hang_id:
        # Tạo lịch hẹn với khách hàng
        env['lich_hen'].create({
            'khach_hang_id': project.khach_hang_id.id,
            'nhan_vien_id': project.phu_trach_id.id if project.phu_trach_id else False,
